import struct
import time
import threading
import hashlib
import hmac
import os
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', os.urandom(32))

# Rate limiter storage: {ip: packed_bucket_bytes}
# Bucket format: [last_refill_time:double][tokens:signed_short][max_tokens:unsigned_short]
# Total: 8 + 2 + 2 = 12 bytes
rate_limit_store = {}
store_lock = threading.Lock()

MAX_TOKENS = 100
REFILL_RATE = 10  # tokens per second
TOKENS_PER_REQUEST = 1
ADMIN_API_COST = 20  # admin operations cost more tokens

# User database (in-memory for demo)
users_db = {}
users_lock = threading.Lock()

def pack_bucket(last_refill, tokens, max_tokens):
    """Pack bucket state into bytes. Uses signed short for tokens to handle
    temporary negative values during concurrent access before refill."""
    return struct.pack('>dhH', last_refill, tokens, max_tokens)

def unpack_bucket(data):
    """Unpack bucket state from bytes."""
    last_refill, tokens, max_tokens = struct.unpack('>dhH', data)
    return last_refill, tokens, max_tokens

def get_bucket(ip):
    """Get or create a token bucket for an IP."""
    if ip not in rate_limit_store:
        rate_limit_store[ip] = pack_bucket(time.time(), MAX_TOKENS, MAX_TOKENS)
    return unpack_bucket(rate_limit_store[ip])

def refill_bucket(last_refill, tokens, max_tokens):
    """Refill tokens based on elapsed time."""
    now = time.time()
    elapsed = now - last_refill
    new_tokens = tokens + int(elapsed * REFILL_RATE)
    if new_tokens > max_tokens:
        new_tokens = max_tokens
    return now, new_tokens, max_tokens

def consume_tokens(ip, cost):
    """Consume tokens from bucket. Returns True if allowed."""
    with store_lock:
        last_refill, tokens, max_tokens = get_bucket(ip)
        last_refill, tokens, max_tokens = refill_bucket(last_refill, tokens, max_tokens)

        if tokens >= cost:
            tokens -= cost
            rate_limit_store[ip] = pack_bucket(last_refill, tokens, max_tokens)
            return True
        else:
            rate_limit_store[ip] = pack_bucket(last_refill, tokens, max_tokens)
            return False

def check_remaining_tokens(ip):
    """Check how many tokens remain for display purposes.
    Note: reads the raw stored value for efficiency (no lock needed for read)."""
    if ip not in rate_limit_store:
        return MAX_TOKENS
    data = rate_limit_store[ip]
    # Optimization: read just the token field directly at offset 8
    # Using unsigned short for display (tokens should never be negative after refill)
    raw_tokens = struct.unpack_from('>H', data, 8)[0]
    return raw_tokens

def rate_limit(cost=TOKENS_PER_REQUEST):
    """Rate limiting decorator."""
    def decorator(f):
        @wraps(f)
        def wrapper(*args, **kwargs):
            ip = request.remote_addr
            remaining = check_remaining_tokens(ip)
            # Fast path: if we clearly have enough tokens, proceed
            if remaining >= cost:
                if not consume_tokens(ip, cost):
                    return jsonify({'error': 'Rate limit exceeded'}), 429
                return f(*args, **kwargs)
            else:
                return jsonify({'error': 'Rate limit exceeded'}), 429
        return wrapper
    return decorator

def hash_password(password, salt=None):
    if salt is None:
        salt = os.urandom(32)
    key = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt + key

def verify_password(stored, password):
    salt = stored[:32]
    expected = stored[32:]
    actual = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(expected, actual)

def require_auth(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        auth = request.authorization
        if not auth or not auth.username or not auth.password:
            return jsonify({'error': 'Authentication required'}), 401
        with users_lock:
            user = users_db.get(auth.username)
        if not user or not verify_password(user['password_hash'], auth.password):
            return jsonify({'error': 'Invalid credentials'}), 401
        g.current_user = user
        return f(*args, **kwargs)
    return wrapper

def require_admin(f):
    @wraps(f)
    @require_auth
    def wrapper(*args, **kwargs):
        if g.current_user.get('role') != 'admin':
            return jsonify({'error': 'Admin access required'}), 403
        return f(*args, **kwargs)
    return wrapper

@app.route('/register', methods=['POST'])
@rate_limit(cost=5)
def register():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing fields'}), 400
    username = str(data['username'])[:64]
    password = str(data['password'])
    if len(password) < 8:
        return jsonify({'error': 'Password too short'}), 400
    with users_lock:
        if username in users_db:
            return jsonify({'error': 'User exists'}), 409
        users_db[username] = {
            'username': username,
            'password_hash': hash_password(password),
            'role': 'user'
        }
    return jsonify({'status': 'created'}), 201

@app.route('/api/profile', methods=['GET'])
@rate_limit(cost=1)
@require_auth
def get_profile():
    user = g.current_user
    return jsonify({'username': user['username'], 'role': user['role']})

@app.route('/api/admin/users', methods=['GET'])
@rate_limit(cost=ADMIN_API_COST)
@require_admin
def admin_list_users():
    with users_lock:
        user_list = [{'username': u, 'role': d['role']} for u, d in users_db.items()]
    return jsonify({'users': user_list})

@app.route('/api/admin/promote', methods=['POST'])
@rate_limit(cost=ADMIN_API_COST)
@require_admin
def admin_promote():
    data = request.get_json()
    if not data or 'username' not in data:
        return jsonify({'error': 'Missing username'}), 400
    target = str(data['username'])
    with users_lock:
        if target not in users_db:
            return jsonify({'error': 'User not found'}), 404
        users_db[target]['role'] = 'admin'
    return jsonify({'status': 'promoted'})

@app.route('/api/status', methods=['GET'])
def get_status():
    """Public endpoint showing rate limit status."""
    ip = request.remote_addr
    remaining = check_remaining_tokens(ip)
    return jsonify({'remaining_tokens': remaining, 'max_tokens': MAX_TOKENS})

@app.route('/api/bulk_check', methods=['POST'])
@rate_limit(cost=50)
@require_auth
def bulk_check():
    """Expensive operation that consumes many tokens."""
    data = request.get_json()
    if not data or 'items' not in data:
        return jsonify({'error': 'Missing items'}), 400
    items = data['items'][:100]  # Cap at 100 items
    results = [{'item': str(i), 'status': 'ok'} for i in items]
    return jsonify({'results': results})

